import {api,icon,esc,dateLabel,minuteLabel,durationLabel,addDays,statusLabel,brand,notify} from '/booking/shared.js';
const root=document.getElementById('admin-root'),dialog=document.getElementById('details-dialog');
const state={view:'overview',session:null,settings:null,bookings:[],blocks:[],today:'',date:'',filter:'all',search:'',selected:null};
const dayNames=['Domingo','Segunda','Terça','Quarta','Quinta','Sexta','Sábado'];
const initials=name=>name.split(' ').filter(Boolean).map(n=>n[0]).slice(0,2).join('').toUpperCase();
async function start(){try{state.session=await api('/api/session');if(!state.session.admin)return renderLogin();await loadData();renderShell();}catch(error){renderError(error.message);}}
function renderError(message){root.innerHTML=`<div class="boot-state">${icon('calendar')}<p>${esc(message)}</p><button class="btn" id="retry-start">Tentar novamente</button></div>`;document.getElementById('retry-start').onclick=start;}
function renderLogin(){root.innerHTML=`<main class="login-layout" id="main-content"><section class="login-art"><img src="/assets/loiro-perolado.jpg" alt="" aria-hidden="true">${brand}<div><p class="label">SEU ESPAÇO DE CUIDADO</p><h1>Organize seus dias.<br><em>Valorize cada encontro.</em></h1><p>Uma agenda feita para o Babi Instituto. Mais tranquilidade para você, mais cuidado em cada atendimento.</p></div><span class="login-art-bottom">BABI INSTITUTO DE BELEZA • POR FABRÍCIA LEÃO</span></section><section class="login-form"><div class="login-form-inner"><div class="login-mark">${icon('shield')}</div><p class="label">ÁREA ADMINISTRATIVA</p><h2>Bem-vinda à sua agenda.</h2><p>${state.session.authenticated?'Esta conta não tem acesso à administração. Entre com a conta proprietária do site.':'Entre para acompanhar os agendamentos, organizar seus horários e preparar os próximos atendimentos.'}</p>${state.session.local?'<button class="btn" id="local-login">Acessar painel local '+icon('arrow')+'</button><div class="login-local">Acesso de desenvolvimento, disponível apenas neste computador.</div>':`<a class="btn" href="/signin-with-chatgpt?return_to=%2Fadmin%2F" target="_top">Entrar com ChatGPT ${icon('arrow')}</a>`}<a class="login-back" href="/">${icon('arrow')} Voltar ao site</a></div></section></main>`;if(state.session.local)document.getElementById('local-login').onclick=async event=>{event.currentTarget.disabled=true;try{await api('/api/local-login',{method:'POST',body:'{}'});await start();}catch(error){notify(error.message,true);event.currentTarget.disabled=false;}};}
async function loadData(){const settings=await api('/api/admin/settings');state.settings=settings;const config=await api('/api/config');state.today=config.today;if(!state.date)state.date=config.today;const month=state.date.slice(0,7),first=month+'-01',last=addDays(addDays(first,32).slice(0,7)+'-01',-1);const result=await api(`/api/admin/bookings?from=${addDays(first,-7)}&to=${addDays(last,7)}`);state.bookings=result.bookings;state.blocks=(await api('/api/admin/blocks')).blocks;}
function sidebar(){return `<aside class="sidebar"><div class="sidebar-brand">${brand}</div><p class="sidebar-label">SEU INSTITUTO</p><nav class="sidebar-nav" aria-label="Administração"><button data-view="overview" class="${state.view==='overview'?'active':''}">${icon('grid')} Visão geral</button><button data-view="agenda" class="${state.view==='agenda'?'active':''}">${icon('calendar')} Agenda</button><button data-view="settings" class="${state.view==='settings'?'active':''}">${icon('settings')} Serviços e horários</button></nav><div class="sidebar-client"><a href="/agendar/" target="_blank" rel="noopener noreferrer">Página da cliente ${icon('up')}</a><p>Veja a experiência de quem<br>vai reservar um momento com você.</p></div><div class="sidebar-bottom"><div class="admin-profile"><img src="/assets/fabricia-leao.jpg" alt="Fabrícia Leão"><div><strong>Fabrícia Leão</strong><small>${state.session.local?'Ambiente local':'Administradora'}</small></div></div>${state.session.local?`<button class="signout" id="signout">${icon('logout')} Sair do painel</button>`:`<a class="signout" href="/signout-with-chatgpt?return_to=%2Fadmin%2F" target="_top">${icon('logout')} Sair do painel</a>`}</div></aside>`;}
function renderShell(){root.innerHTML=`${sidebar()}<main class="admin-main" id="main-content"><header class="admin-topbar"><p class="label">BABI / ${state.view==='settings'?'CONFIGURAÇÕES':'ADMINISTRAÇÃO'}</p><div class="topbar-actions"><span class="live-dot">${state.settings.enabled?'Agenda online ativa':'Agenda online pausada'}</span><button class="icon-btn" id="refresh" aria-label="Atualizar agenda">${icon('refresh')}</button></div></header><div id="view-content"></div><footer class="admin-footer"><span>Um cuidado especial começa com uma agenda organizada.</span><span>BABI INSTITUTO DE BELEZA</span></footer></main>`;
root.querySelectorAll('[data-view]').forEach(button=>button.onclick=()=>{state.view=button.dataset.view;renderShell();});
document.getElementById('refresh').onclick=async()=>{try{await loadData();renderShell();notify('Agenda atualizada.');}catch(error){notify(error.message,true);}};
document.getElementById('signout')?.addEventListener('click',async()=>{await api('/api/local-logout',{method:'POST',body:'{}'});await start();});
if(state.view==='settings')renderSettings();else renderAgenda();}
function renderAgenda(){const selectedDay=state.bookings.filter(b=>b.date===state.date),nextWeek=state.bookings.filter(b=>b.date>=state.date&&b.date<=addDays(state.date,6)&&b.status==='confirmed'),unique=new Set(state.bookings.filter(b=>b.status!=='cancelled').map(b=>b.phone));
document.getElementById('view-content').innerHTML=`<div class="page-title"><div><h1>${state.view==='overview'?'Seu dia, em boas mãos.':'Cada encontro, no seu lugar.'}</h1><p>${state.view==='overview'?'Bem-vinda, Fabrícia. Aqui, cada momento tem o seu lugar.':'Acompanhe os horários e cuide dos próximos atendimentos.'}</p></div><span class="date-pill">${icon('calendar')}${esc(dateLabel(state.today,{day:'numeric',month:'long',year:'numeric'}))}</span></div>${!state.settings.enabled?`<div class="notice">${icon('settings')}<span>A agenda online está pausada. Revise os serviços, durações e horários antes de ativar.</span><button id="open-settings">Configurar agenda ${icon('up')}</button></div>`:''}${state.view==='overview'?`<section class="welcome-banner"><div class="welcome-copy"><p class="label">TEMPO PARA O QUE IMPORTA</p><h2>Mais organização.<br><em>Mais espaço para transformar.</em></h2><p>Os horários reservados pelas clientes aparecem aqui, com confirmação automática.</p></div><div class="welcome-photo"><img src="/assets/cachos.jpg" alt="" aria-hidden="true">${icon('flower')}</div></section><section class="metrics" aria-label="Resumo da agenda"><article class="metric"><div class="metric-head">Atendimentos no dia ${icon('calendar')}</div><strong>${selectedDay.filter(b=>b.status!=='cancelled').length.toString().padStart(2,'0')}</strong><span>${esc(dateLabel(state.date))}</span></article><article class="metric"><div class="metric-head">Próximos 7 dias ${icon('check')}</div><strong>${String(nextWeek.length).padStart(2,'0')}</strong><span>Horários confirmados</span></article><article class="metric"><div class="metric-head">Clientes no período ${icon('users')}</div><strong>${String(unique.size).padStart(2,'0')}</strong><span>Na agenda carregada deste mês</span></article><article class="metric"><div class="metric-head">Cancelamentos ${icon('clock')}</div><strong>${String(state.bookings.filter(b=>b.status==='cancelled').length).padStart(2,'0')}</strong><span>Na agenda carregada deste mês</span></article></section>`:''}<section class="panel" aria-label="Agenda de atendimentos"><div class="panel-header"><div><h2>Sua agenda</h2><p>Os próximos momentos de beleza começam aqui.</p></div><a class="btn" href="/agendar/" target="_blank" rel="noopener noreferrer">${icon('plus')} Novo agendamento</a></div><div class="week-strip">${weekStrip()}</div><div class="table-toolbar"><div><h3>${esc(dateLabel(state.date,{weekday:'long',day:'numeric',month:'long'}))}</h3></div><input class="date-picker" id="agenda-date" type="date" value="${state.date}" aria-label="Escolher dia da agenda"><label class="search-field">${icon('search')}<input id="search-bookings" type="search" placeholder="Buscar cliente ou serviço" value="${esc(state.search)}" aria-label="Buscar cliente ou serviço"></label></div><div class="table-filters" role="group" aria-label="Filtrar por situação">${[['all','Todos'],['confirmed','Confirmados'],['completed','Concluídos'],['cancelled','Cancelados']].map(([value,label])=>`<button data-status="${value}" class="${state.filter===value?'active':''}" aria-pressed="${state.filter===value}">${label}</button>`).join('')}</div><div id="appointment-results"></div><div class="table-footer"><span class="live-dot">Confirmação automática</span><span>Horários no fuso de Salvador • America/Bahia</span></div></section>`;
document.getElementById('open-settings')?.addEventListener('click',()=>{state.view='settings';renderShell();});
document.getElementById('agenda-date').onchange=async event=>{if(!event.target.value)return;state.date=event.target.value;try{await loadData();renderAgenda();}catch(error){notify(error.message,true);}};
root.querySelectorAll('[data-day]').forEach(button=>button.onclick=async()=>{state.date=button.dataset.day;try{await loadData();renderAgenda();}catch(error){notify(error.message,true);}});
document.getElementById('search-bookings').oninput=event=>{state.search=event.target.value;renderRows();};
root.querySelectorAll('[data-status]').forEach(button=>button.onclick=()=>{state.filter=button.dataset.status;root.querySelectorAll('[data-status]').forEach(el=>{el.classList.toggle('active',el===button);el.setAttribute('aria-pressed',String(el===button));});renderRows();});renderRows();}
function weekStrip(){const weekday=new Date(state.date+'T12:00:00Z').getUTCDay(),monday=addDays(state.date,-((weekday+6)%7));return Array.from({length:7},(_,i)=>{const date=addDays(monday,i),has=state.bookings.some(b=>b.date===date&&b.status!=='cancelled');return `<button class="week-day ${state.date===date?'active':''} ${state.today===date?'today':''}" data-day="${date}" aria-label="${esc(dateLabel(date,{weekday:'long',day:'numeric',month:'long'}))}" aria-pressed="${state.date===date}"><span>${esc(dateLabel(date,{weekday:'short'}).replace('.',''))}</span><strong>${Number(date.slice(-2))}</strong><i class="${has?'':'empty'}"></i></button>`;}).join('');}
function renderRows(){const query=state.search.toLocaleLowerCase('pt-BR'),rows=state.bookings.filter(b=>b.date===state.date&&(state.filter==='all'||b.status===state.filter)&&[b.customer_name,b.service_name,b.phone].join(' ').toLocaleLowerCase('pt-BR').includes(query));const area=document.getElementById('appointment-results');if(!rows.length){area.innerHTML=`<div class="empty-state"><div class="empty-icon">${icon('calendar')}</div><h3>${state.search||state.filter!=='all'?'Nenhum resultado com esse filtro.':'Um novo dia, muitas possibilidades.'}</h3><p>${state.search||state.filter!=='all'?'Tente outro nome, serviço ou situação para encontrar um atendimento.':'Os agendamentos deste dia aparecerão aqui. Compartilhe a página da cliente quando sua agenda estiver pronta.'}</p><a class="btn btn-secondary" href="/agendar/" target="_blank" rel="noopener noreferrer">Ver página da cliente ${icon('up')}</a></div>`;return;}
area.innerHTML=`<div class="table-wrap"><table class="appointments-table"><thead><tr><th>Cliente</th><th>Serviço</th><th>Horário</th><th>Situação</th><th><span class="muted">Detalhes</span></th></tr></thead><tbody>${rows.map(b=>`<tr><td><div class="client-cell"><span class="initial-avatar">${esc(initials(b.customer_name))}</span><div><strong>${esc(b.customer_name)}</strong><small>${esc(b.phone)}</small></div></div></td><td class="table-service"><strong>${esc(b.service_name)}</strong><small>${durationLabel(b.duration)}</small></td><td class="time-cell"><strong>${minuteLabel(b.start_minute)}</strong><small>até ${minuteLabel(b.start_minute+b.duration)}</small></td><td><span class="status ${b.status}">${statusLabel[b.status]}</span></td><td><button class="icon-btn" data-booking="${b.id}" aria-label="Ver agendamento de ${esc(b.customer_name)}">${icon('chevron')}</button></td></tr>`).join('')}</tbody></table></div>`;area.querySelectorAll('[data-booking]').forEach(button=>button.onclick=()=>openBooking(button.dataset.booking));}
function openBooking(id){state.selected=state.bookings.find(b=>b.id===id);renderDetails();if(!dialog.open)dialog.showModal();}
function renderDetails(){const b=state.selected;dialog.innerHTML=`<div class="dialog-top"><div><h2 id="dialog-title">Seu próximo encontro</h2><p>AGENDAMENTO BABI-${b.id.slice(0,8).toUpperCase()}</p></div><button class="icon-btn" id="close-dialog" aria-label="Fechar detalhes">${icon('close')}</button></div><div class="dialog-body"><div class="dialog-client"><span class="initial-avatar">${esc(initials(b.customer_name))}</span><div><h3>${esc(b.customer_name)}</h3><a href="tel:+${b.phone.length<=11?"55":""}${esc(b.phone)}">${esc(b.phone)}</a></div></div><dl class="detail-grid"><div><dt>Serviço</dt><dd>${esc(b.service_name)}</dd></div><div><dt>Situação</dt><dd><span class="status ${b.status}">${statusLabel[b.status]}</span></dd></div><div><dt>Data</dt><dd>${esc(dateLabel(b.date,{day:'numeric',month:'long',year:'numeric'}))}</dd></div><div><dt>Horário</dt><dd>${minuteLabel(b.start_minute)} às ${minuteLabel(b.start_minute+b.duration)} · ${durationLabel(b.duration)}</dd></div></dl>${b.notes?`<div class="dialog-notes">${esc(b.notes)}</div>`:''}${b.status==='confirmed'?`<div class="dialog-actions"><button class="btn btn-secondary" id="reschedule">Reagendar</button><button class="btn btn-success" id="complete-booking">${icon('check')} Concluir</button><button class="btn btn-danger" id="cancel-booking">Cancelar</button></div><div id="booking-extra"></div>`:''}</div>`;
document.getElementById('close-dialog').onclick=()=>dialog.close();document.getElementById('complete-booking')?.addEventListener('click',()=>mutateBooking({status:'completed'}));document.getElementById('cancel-booking')?.addEventListener('click',()=>{document.getElementById('booking-extra').innerHTML=`<div class="reschedule-form"><p>Cancelar o atendimento de ${esc(b.customer_name)}? O horário ficará disponível novamente para outras clientes.</p><button class="btn btn-danger" id="confirm-cancel">Sim, cancelar atendimento</button></div>`;document.getElementById('confirm-cancel').onclick=()=>mutateBooking({status:'cancelled'});});document.getElementById('reschedule')?.addEventListener('click',renderReschedule);}
async function mutateBooking(data){const buttons=dialog.querySelectorAll('button');buttons.forEach(b=>b.disabled=true);try{await api(`/api/admin/bookings/${state.selected.id}`,{method:'PATCH',body:JSON.stringify({...data,revision:state.selected.revision})});dialog.close();await loadData();renderAgenda();notify(data.status==='cancelled'?'Atendimento cancelado. O horário foi liberado.':data.status==='completed'?'Atendimento concluído.':'Atendimento reagendado.');}catch(error){notify(error.message,true);buttons.forEach(b=>b.disabled=false);}}
function renderReschedule(){const b=state.selected;document.getElementById('booking-extra').innerHTML=`<form id="reschedule-form" class="reschedule-form"><p>Escolha uma nova data e consulte os horários. A duração original do atendimento será preservada.</p><div class="form-two"><label class="field">Nova data<input type="date" id="new-date" value="${b.date}" min="${state.today}" required></label><label class="field">Novo horário<select id="new-time" required><option value="">Escolha uma data</option></select></label></div><button class="btn" id="save-reschedule" disabled>Salvar novo horário ${icon('check')}</button><p id="reschedule-message"></p></form>`;
const dateInput=document.getElementById('new-date'),select=document.getElementById('new-time'),save=document.getElementById('save-reschedule');async function fetchSlots(){select.innerHTML='<option value="">Consultando...</option>';save.disabled=true;try{const data=await api(`/api/admin/availability?date=${dateInput.value}&booking=${b.id}`);select.innerHTML='<option value="">Escolher horário</option>'+data.slots.map(t=>`<option value="${t}">${t}</option>`).join('');document.getElementById('reschedule-message').textContent=data.slots.length?'':data.reason;}catch(error){document.getElementById('reschedule-message').textContent=error.message;}}dateInput.onchange=fetchSlots;select.onchange=()=>save.disabled=!select.value;document.getElementById('reschedule-form').onsubmit=event=>{event.preventDefault();mutateBooking({date:dateInput.value,time:select.value});};fetchSlots();}
dialog.addEventListener('click',event=>{if(event.target===dialog)dialog.close();});
function renderSettings(){const s=state.settings;document.getElementById('view-content').innerHTML=`<div class="page-title"><div><h1>Uma agenda do seu jeito.</h1><p>Defina o que você oferece e quando cada encontro pode acontecer.</p></div></div><div class="notice">${icon('clock')}<span>${state.settings.enabled?'As alterações valem para novos agendamentos. Reservas existentes mantêm a duração original.':'Os horários e durações abaixo são sugestões iniciais. Revise e salve antes de abrir a agenda.'}</span></div><form id="settings-form"><div class="settings-layout"><div><section class="panel"><div class="panel-header"><div><h2>Seus serviços</h2><p>Nome, descrição e duração de cada cuidado.</p></div>${icon('flower')}</div><div class="settings-body">${s.services.map((service,index)=>`<div class="service-setting" data-service-index="${index}"><div class="service-setting-title"><input type="checkbox" name="service-active-${index}" ${service.active?'checked':''} aria-label="Ativar ${esc(service.name)}"><input type="text" name="service-name-${index}" value="${esc(service.name)}" minlength="3" maxlength="70" required aria-label="Nome do serviço ${index+1}"></div><div class="service-setting-meta"><label class="field">Descrição<input name="service-description-${index}" value="${esc(service.description)}" maxlength="180"></label><label class="field">Duração (min)<input type="number" name="service-duration-${index}" value="${service.duration}" min="15" max="480" step="15" required></label></div></div>`).join('')}</div></section><section class="panel"><div class="panel-header"><div><h2>Dias e horários</h2><p>Ative os dias de atendimento e o intervalo disponível.</p></div>${icon('calendar')}</div><div class="settings-body">${s.weekly.map(day=>`<div class="day-setting"><label class="checkbox-label"><input type="checkbox" name="day-enabled-${day.day}" ${day.enabled?'checked':''}>${dayNames[day.day]}</label><input type="time" step="900" name="day-open-${day.day}" value="${day.open}" required aria-label="Abertura de ${dayNames[day.day]}"><span>–</span><input type="time" step="900" name="day-close-${day.day}" value="${day.close}" required aria-label="Fechamento de ${dayNames[day.day]}"></div>`).join('')}</div></section></div><div class="settings-right"><section class="panel"><div class="panel-header"><div><h2>Agendamento online</h2><p>Você decide quando abrir sua agenda.</p></div>${icon('settings')}</div><div class="settings-body"><div class="toggle-box"><label class="checkbox-label"><input name="online-enabled" type="checkbox" ${s.enabled?'checked':''}>Ativar agendamento online</label><p>As clientes escolhem um horário e recebem a confirmação automaticamente.</p></div><label class="field">Antecedência mínima (minutos)<input name="lead-minutes" type="number" value="${s.leadMinutes}" min="0" max="2880" required><small>Tempo entre a reserva e o início do atendimento.</small></label><label class="field">Abrir agenda para os próximos (dias)<input name="advance-days" type="number" value="${s.advanceDays}" min="1" max="180" required></label><p class="muted" style="font-size:8px;line-height:1.9">Fuso horário: Salvador / Bahia.<br>Não há envio automático de mensagens ou cobrança nesta etapa.</p></div></section><section class="panel"><div class="panel-header"><div><h2>Uma pausa na agenda</h2><p>Bloqueie folgas ou intervalos específicos.</p></div>${icon('clock')}</div><div class="settings-body"><div id="block-fields"><label class="field">Data<input type="date" id="block-date" min="${state.today}"></label><label class="checkbox-label" style="margin-bottom:17px"><input id="block-all-day" type="checkbox" checked>Dia inteiro</label><div class="form-two" id="block-times" hidden><label class="field">De<input type="time" id="block-start" value="12:00" step="900"></label><label class="field">Até<input type="time" id="block-end" value="13:00" step="900"></label></div><label class="field">Observação (só para você)<input id="block-note" maxlength="150" placeholder="Ex.: folga, almoço, compromisso"></label><button type="button" class="btn btn-secondary" id="save-block">${icon('plus')} Bloquear horário</button></div><div class="blocks-list" id="blocks-list"></div></div></section></div></div><div class="settings-save"><button class="btn" type="submit" id="save-settings">Salvar configurações ${icon('check')}</button></div></form>`;
document.getElementById('settings-form').onsubmit=async event=>{event.preventDefault();const form=new FormData(event.currentTarget),button=document.getElementById('save-settings');const data={...s,enabled:form.has('online-enabled'),leadMinutes:Number(form.get('lead-minutes')),advanceDays:Number(form.get('advance-days')),services:s.services.map((service,index)=>({...service,name:form.get(`service-name-${index}`),description:form.get(`service-description-${index}`),duration:Number(form.get(`service-duration-${index}`)),active:form.has(`service-active-${index}`)})),weekly:s.weekly.map(day=>({...day,enabled:form.has(`day-enabled-${day.day}`),open:form.get(`day-open-${day.day}`),close:form.get(`day-close-${day.day}`)}))};button.disabled=true;try{state.settings=await api('/api/admin/settings',{method:'PUT',body:JSON.stringify(data)});notify('Configurações salvas. '+(data.enabled?'Sua agenda online está ativa.':'A agenda online continua pausada.'));renderShell();}catch(error){notify(error.message,true);button.disabled=false;}};
document.getElementById('block-all-day').onchange=event=>document.getElementById('block-times').hidden=event.target.checked;
document.getElementById('save-block').onclick=async event=>{const data={date:document.getElementById('block-date').value,allDay:document.getElementById('block-all-day').checked,start:document.getElementById('block-start').value,end:document.getElementById('block-end').value,note:document.getElementById('block-note').value};if(!data.date)return notify('Escolha a data que deseja bloquear.',true);event.currentTarget.disabled=true;try{await api('/api/admin/blocks',{method:'POST',body:JSON.stringify(data)});state.blocks=(await api('/api/admin/blocks')).blocks;renderBlocks();notify('Pausa adicionada à agenda.');}catch(error){notify(error.message,true);}finally{document.getElementById('save-block').disabled=false;}};renderBlocks();}
function renderBlocks(){document.getElementById('blocks-list').innerHTML=state.blocks.length?state.blocks.map(block=>`<div class="block-row"><div><strong>${esc(dateLabel(block.date))} · ${block.start_minute===0&&block.end_minute===1440?'dia inteiro':`${minuteLabel(block.start_minute)} – ${minuteLabel(block.end_minute)}`}</strong><small>${esc(block.note||'Pausa na agenda')}</small></div><button type="button" class="icon-btn" data-remove-block="${block.id}" aria-label="Remover pausa de ${esc(dateLabel(block.date))}">${icon('close')}</button></div>`).join(''):'<p style="font-size:9px;color:var(--muted)">Nenhuma pausa cadastrada.</p>';root.querySelectorAll('[data-remove-block]').forEach(button=>button.onclick=async()=>{button.disabled=true;try{await api('/api/admin/blocks/'+button.dataset.removeBlock,{method:'DELETE',body:'{}'});state.blocks=state.blocks.filter(b=>b.id!==button.dataset.removeBlock);renderBlocks();notify('Pausa removida.');}catch(error){notify(error.message,true);button.disabled=false;}});}
setInterval(async()=>{if(state.session?.admin&&state.view!=='settings'&&!dialog.open&&document.visibilityState==='visible'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName)){try{await loadData();renderAgenda();}catch{ /* preserve the last loaded agenda during a temporary connection failure */ }}},30000);
start();
